insert into public.ingredientes (inci, nombre_es, funciones, restriccion, rango_uso, que_es, origen, fuente, categoria, precauciones, parte_usada, verificado) values
  ('Dicaprylyl Carbonate', 'Carbonato de dicaprililo', array['Emoliente']::text[], null, '2-15%', 'Emoliente ligero y seco derivado de aceites vegetales. Muy buena extensión.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('C15-19 Alkane', 'Alcano vegetal (C15-19)', array['Emoliente']::text[], null, '2-10%', 'Hidrocarburos ligeros de origen vegetal, usados como alternativa natural a las siliconas en el tacto seco.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Hydrolyzed Jojoba Esters', 'Ésteres de jojoba hidrolizados', array['Emoliente', 'Estructurante']::text[], null, '1-10%', 'Cera de jojoba procesada, en perlas o polvo. Se usa en exfoliantes suaves y barras.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Glyceryl Caprylate', 'Caprilato de glicerilo', array['Emoliente', 'Potenciador de conservante']::text[], null, '0.3-1%', 'Éster de glicerina y ácido caprílico. Emoliente que también refuerza la acción de los conservantes.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Cholesterol', 'Colesterol', array['Acondicionador de piel', 'Emoliente']::text[], null, '0.5-2%', 'Lípido de la barrera cutánea. En cosmética restaura la barrera junto a ceramidas y ácidos grasos (proporción aproximada 1:1:1).', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Phytosphingosine', 'Fitoesfingosina', array['Acondicionador de piel', 'Antimicrobiano']::text[], null, '0.1-0.5%', 'Lípido parecido a las esfingosinas de la barrera cutánea. Se usa en piel con tendencia a acné y barrera dañada.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Kaolin', 'Caolín (arcilla blanca)', array['Absorbente', 'Matificante', 'Abrasivo suave']::text[], null, '10-100% en mascarillas', 'La arcilla más suave: absorbe poco y limpia sin resecar. Apta para piel sensible, mixta o seca, y base de polvos y mascarillas.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'No inhalar el polvo. No usar utensilios metálicos al mezclar', null, false),
  ('Illite', 'Arcilla verde (illita)', array['Absorbente', 'Astringente']::text[], null, '10-100% en mascarillas', 'Arcilla de grano fino, muy absorbente. Se usa en piel grasa o con imperfecciones. El color verde se debe a restos de materia orgánica y óxidos de hierro.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Puede resecar si se deja secar del todo sobre la piel. No usar utensilios metálicos', null, false),
  ('Red Clay', 'Arcilla roja', array['Absorbente']::text[], null, '10-100%', 'Arcilla rica en óxidos de hierro, de absorción media. Se usa en piel sensible o con rojeces y en cabello.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Puede teñir piel clara o telas', null, false),
  ('Yellow Clay', 'Arcilla amarilla', array['Absorbente']::text[], null, '10-100%', 'Illita con hidróxidos de hierro. Absorción media y limpia con suavidad; se usa para piel apagada y como base de mascarillas.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', null, null, false),
  ('Pink Clay', 'Arcilla rosa', array['Absorbente']::text[], null, '10-100%', 'Mezcla de caolín y arcilla roja. La más suave de las coloreadas, ideal para piel sensible o seca.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', null, null, false),
  ('Black Clay', 'Arcilla negra', array['Absorbente']::text[], null, '10-100% en mascarillas', 'Su composición cambia según el proveedor (suele ser una mezcla de arcillas con minerales oscuros o con carbón). Pide la ficha técnica a tu proveedor.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Composición variable', null, false),
  ('Montmorillonite', 'Montmorillonita', array['Absorbente', 'Espesante']::text[], null, '10-100% en mascarillas', 'Arcilla del grupo de las esmectitas, de mucha capacidad de hinchamiento y absorción. La bentonita es una arcilla de este tipo.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', null, null, false),
  ('Moroccan Lava Clay', 'Rhassoul (ghassoul)', array['Absorbente', 'Tensioactivo limpiador']::text[], null, 'Mascarillas y lavado', 'Arcilla marroquí rica en magnesio y silicio. Limpia con suavidad y deja una sensación sedosa en piel y cabello.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', null, null, false),
  ('Diatomaceous Earth', 'Tierra de diatomeas', array['Absorbente', 'Abrasivo suave']::text[], null, '1-10%', 'Sílice fósil de microalgas. Abrasivo suave y absorbente, usado en exfoliantes y dentífricos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'No inhalar el polvo (sílice)', null, false),
  ('Charcoal Powder', 'Carbón activado', array['Absorbente']::text[], null, '1-10% en mascarillas; 0.5-2% en jabones', 'Polvo de carbón muy poroso que adsorbe impurezas, sebo superficial y olores. La idea de "detox profundo" es marketing: limpia la superficie, como una arcilla.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Mancha telas y lavamanos. No inhalar el polvo', null, false),
  ('Zinc Oxide', 'Óxido de zinc', array['Protector', 'Absorbente', 'Astringente', 'Filtro UV']::text[], 'UE: como filtro UV hasta 25%; la forma nano tiene restricciones', '1-5% como matificante o protector; 15-25% como filtro solar', 'Mineral blanco de acción muy amplia: protector físico de la piel, astringente y filtro solar físico (UVA y UVB). Ayuda en dermatitis del pañal y en productos para piel grasa.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'No inhalar el polvo. Dispersarlo bien en aceite o glicerina: forma grumos blancos. En protector solar casero no garantiza el factor', null, false),
  ('Titanium Dioxide', 'Dióxido de titanio', array['Pigmento', 'Filtro UV', 'Absorbente']::text[], 'Restringido por inhalación en productos en polvo y aerosol: revisa tu normativa', '1-5% como pigmento o blanqueador', 'Pigmento blanco opacificante y filtro solar físico. Da cobertura y blanquea.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Dispersar primero en un poco de glicerina o aceite: en seco forma grumos blancos. No inhalar el polvo. Usado así no es un protector solar', null, false),
  ('Iron Oxides', 'Óxidos de hierro (CI 77491, 77492, 77499)', array['Pigmento', 'Colorante']::text[], null, '0.1-5% según el tono', 'Pigmentos minerales rojos, amarillos y negros, muy estables. Se mezclan para lograr tonos de piel, tierra y marrón en bases, polvos y labiales.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'No inhalar el polvo', null, false),
  ('Mica', 'Mica (CI 77019)', array['Pigmento', 'Brillo']::text[], null, '2-20% en polvos', 'Mineral en láminas finas que da brillo y efecto perlado a polvos, iluminadores y labiales.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Elige proveedores con abastecimiento ético certificado. No inhalar el polvo', null, false),
  ('Ultramarines', 'Ultramarinos (CI 77007)', array['Pigmento']::text[], null, '0.1-5%', 'Pigmentos minerales azules, violetas o rosados, estables y de baja toxicidad.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'No inhalar el polvo', null, false),
  ('Chromium Oxide Greens', 'Óxido de cromo verde (CI 77288)', array['Pigmento']::text[], null, '0.1-5%', 'Pigmento mineral verde, muy estable. Se usa en cosmética de color.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'No inhalar el polvo', null, false),
  ('Calcium Carbonate', 'Carbonato de calcio', array['Absorbente', 'Abrasivo suave']::text[], null, '5-30%', 'Mineral blanco, abrasivo suave usado en dentífricos, polvos y exfoliantes.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', null, null, false),
  ('Magnesium Carbonate', 'Carbonato de magnesio', array['Absorbente']::text[], null, '1-10%', 'Polvo muy ligero y absorbente, de tacto sedoso.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'No inhalar el polvo', null, false),
  ('Magnesium Sulfate', 'Sulfato de magnesio (sal de Epsom)', array['Mineral', 'Exfoliante']::text[], null, '10-100% en sales de baño', 'Sal de baño tradicional. Se usa en sales y baños de pies.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Los efectos de que "el magnesio se absorba por la piel" no están bien demostrados', null, false),
  ('Maris Sal', 'Sal de mar', array['Exfoliante', 'Mineral']::text[], null, '10-100% en exfoliantes', 'Sal marina entera, con minerales traza. Se usa en exfoliantes corporales y baños.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Irrita piel con heridas; evitar en rostro', null, false),
  ('Potassium Alum', 'Alumbre potásico', array['Desodorante', 'Astringente']::text[], null, '10-15% en barra; solución saturada en spray', 'Sal mineral con acción astringente y antibacteriana suave. Se usa como desodorante.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Puede irritar la piel afeitada', null, false),
  ('Maris Limus', 'Barro marino (lodo de mar)', array['Mineral', 'Absorbente']::text[], null, '10-100%', 'Barro de mar o de salinas, rico en minerales. Se usa en mascarillas corporales.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', null, null, false),
  ('Zeolite', 'Zeolita', array['Absorbente', 'Desodorante']::text[], null, '1-10%', 'Mineral volcánico poroso que adsorbe olores y humedad.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'No inhalar el polvo', null, false),
  ('Talc', 'Talco', array['Absorbente', 'Agente de carga']::text[], null, 'Evitar', 'Silicato de magnesio muy suave. Se evita en polvos por riesgo de contaminación con asbesto si no es de grado cosmético y por inhalación.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'No inhalar. Alternativas: almidón, arrowroot, caolín', null, false),
  ('Juglans Regia Shell Powder', 'Cáscara de nuez molida', array['Exfoliante', 'Abrasivo suave']::text[], null, '5-20%', 'Exfoliante físico de grano fino a medio. Usado en exfoliantes corporales.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Los granos angulosos pueden irritar el rostro; evitar si hay alergia a frutos secos', null, false),
  ('Prunus Armeniaca Seed Powder', 'Carozo de damasco molido', array['Exfoliante', 'Abrasivo suave']::text[], null, '5-20%', 'Exfoliante físico, algo más suave que la cáscara de nuez.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Puede dar microcortes en el rostro; evitar si hay alergia a rosáceas', null, false),
  ('Coffea Arabica Seed Powder', 'Café molido', array['Exfoliante', 'Estimulante']::text[], null, '10-50% en exfoliantes', 'Café usado o recién molido como exfoliante corporal. Aporta cafeína y aroma.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Puede tapar desagües y teñir', null, false),
  ('Sucrose', 'Azúcar', array['Exfoliante', 'Humectante']::text[], null, '30-60% en exfoliantes', 'Cristales de azúcar para exfoliantes corporales: se disuelven con el agua.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Se disuelve en contacto con agua: no guardar en baños húmedos', null, false),
  ('Oryza Sativa Bran Powder', 'Salvado de arroz', array['Exfoliante', 'Absorbente']::text[], null, '5-30%', 'Polvo de salvado de arroz, usado como exfoliante suave y en mascarillas.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', null, null, false),
  ('Theobroma Cacao Seed Powder', 'Cacao en polvo', array['Colorante', 'Antioxidante']::text[], null, '2-10%', 'Cacao sin azúcar. Aporta color marrón y polifenoles; se usa en mascarillas y bases de maquillaje natural.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Puede teñir. En productos con agua se contamina fácil', null, false),
  ('Beta Vulgaris Root Powder', 'Betarraga (remolacha) en polvo', array['Colorante']::text[], null, '1-5%', 'Polvo de remolacha. Da color rosado a rojo; poco estable a luz y calor.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Destiñe y se degrada rápido', null, false),
  ('Indigofera Tinctoria Leaf Powder', 'Índigo (añil) en polvo', array['Tintura capilar', 'Colorante']::text[], null, 'Según la receta', 'Polvo vegetal que, junto con la henna, da tonos oscuros al cabello.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Puede teñir piel y telas', null, false),
  ('Lawsonia Inermis Leaf Powder', 'Henna', array['Tintura capilar', 'Acondicionador capilar']::text[], null, 'Según la receta', 'Polvo de hoja que tiñe el cabello de rojizo (lawsona) y lo recubre, dándole cuerpo y fuerza.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'El tinte es permanente. Evita la "henna negra": suele traer PPD, un alérgeno grave', null, false),
  ('Cassia Obovata Flower Powder', 'Cassia (henna neutra)', array['Acondicionador capilar']::text[], null, 'Según la receta', 'Polvo que acondiciona y da brillo al cabello sin teñir de forma marcada.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'En cabello rubio puede dar un tono amarillento', null, false),
  ('Bixa Orellana Seed Extract', 'Achiote (annatto)', array['Colorante']::text[], null, '0.1-2%', 'Colorante natural naranja-rojizo de las semillas del achiote.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Tiñe; puede sensibilizar en algunas personas', null, false),
  ('Alkanna Tinctoria Root Extract', 'Raíz de alkanna', array['Colorante']::text[], null, '0.1-2%', 'Pigmento rojo-violáceo liposoluble de la raíz de la alkanna. Se usa en labiales y bálsamos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Puede contener trazas de alcaloides pirrolizidínicos: usar grado cosmético', null, false),
  ('Capsicum Annuum Fruit Powder', 'Pimentón (paprika) en polvo', array['Colorante']::text[], null, '0.1-2%', 'Polvo rojo-anaranjado de pimiento, usado como pigmento natural suave.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Arcillas, minerales y pigmentos', 'Irrita ojos y mucosas', null, false),
  ('Parfum', 'Fragancia (perfume)', array['Fragancia']::text[], 'Declarar alérgenos sobre 0.001% (se dejan) o 0.01% (se enjuagan)', 'Según el producto', 'Mezcla de aromas sintéticos o naturales. Los aceites esenciales no se declaran como "Parfum", sino por su nombre, pero sí hay que declarar los alérgenos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Otros ingredientes', 'Los 26 alérgenos de fragancia deben declararse sobre cierto umbral en la UE', null, false),
  ('Sodium Borate', 'Bórax (borato de sodio)', array['Regulador de pH', 'Emulsionante']::text[], 'Restringido en la UE', 'Según la receta', 'Sal mineral usada en cremas antiguas con cera de abeja: reacciona con ella y forma un emulsionante.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Otros ingredientes', 'Está restringido o prohibido en cosmética en varios países, sobre todo en productos para niños y en piel con heridas. Revisa tu normativa antes de usarlo', null, false),
  ('Sodium Carbonate', 'Carbonato de sodio (soda ash)', array['Regulador de pH']::text[], null, 'Según la receta', 'Base más débil que la soda cáustica. Sube el pH de sales y jabones en polvo.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Otros ingredientes', 'Irritante en polvo. Alcaliniza', null, false),
  ('Sodium Sesquicarbonate', 'Sesquicarbonato de sodio', array['Regulador de pH']::text[], null, 'Según la receta', 'Sal alcalina intermedia entre el bicarbonato y el carbonato.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Otros ingredientes', 'Alcaliniza', null, false),
  ('Glyceryl Laurate', 'Laurato de glicerilo', array['Antimicrobiano', 'Emoliente']::text[], null, '0.5-2%', 'Éster de glicerina y ácido láurico, con acción antimicrobiana suave. Se usa en desodorantes y como booster de conservantes.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Otros ingredientes', null, null, false),
  ('Cetyl Hydroxyethylcellulose', 'Cetil hidroxietilcelulosa', array['Espesante', 'Estabilizante']::text[], null, '0.3-1%', 'Espesante celulósico modificado que estabiliza emulsiones y da cuerpo a geles.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Otros ingredientes', null, null, false),
  ('Beeswax Absolute', 'Cera de abeja absoluta', array['Fragancia']::text[], null, '0.1-1%', 'Extracto con aroma a miel de la cera de abeja. Se usa en perfumería natural.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Otros ingredientes', 'Alérgeno en personas sensibles a los productos de las abejas', null, false),
  ('Alcohol Denat.', 'Alcohol desnaturalizado', array['Disolvente', 'Astringente']::text[], null, '5-50%', 'Etanol con sustancias que lo hacen no apto para beber. Se usa como disolvente y astringente.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Otros ingredientes', 'Reseca; no es adecuado para tinturas de uso interno', null, false),
  ('Sodium Magnesium Silicate', 'Silicato de sodio y magnesio (arcilla sintética)', array['Espesante', 'Suspensor']::text[], null, '0.5-3%', 'Arcilla sintética que forma geles transparentes y suspende partículas.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Otros ingredientes', null, null, false),
  ('Polyquaternium-10', 'Polyquaternium-10', array['Acondicionador capilar', 'Antiestático']::text[], null, '0.1-1%', 'Polímero catiónico derivado de la celulosa; acondiciona y reduce la electricidad estática. No es natural.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Otros ingredientes', 'Incompatible con aniónicos fuertes', null, false),
  ('Guar Hydroxypropyltrimonium Chloride', 'Guar catiónico', array['Acondicionador capilar']::text[], null, '0.1-0.5%', 'Guar modificada con carga positiva. Acondiciona y desenreda sin siliconas.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Otros ingredientes', 'Incompatible con aniónicos fuertes', null, false),
  ('Glycol Distearate', 'Diestearato de glicol', array['Estructurante']::text[], null, '1-3%', 'Cera que da nacarado a champús y geles.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Otros ingredientes', null, null, false),
  ('Cocos Nucifera Husk Powder', 'Fibra de coco (cáscara molida)', array['Exfoliante', 'Abrasivo suave']::text[], null, '5-20%', 'Fibra de la cáscara del coco molida, usada como exfoliante físico.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Otros ingredientes', null, null, false),
  ('Sodium Cocoyl Isethionate', 'SCI (cocoil isetionato de sodio)', array['Tensioactivo limpiador', 'Espumante']::text[], null, '30-60% en barras; 5-15% en líquidos', 'Tensioactivo aniónico suave derivado del coco, en escamas o polvo. Base de los syndets de alta cosmética: espuma densa y cremosa, pH 5.5-6.5, y deposita emolientes al enjuagar. Funde a ~55 °C.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'Incompatible con tensioactivos catiónicos (BTMS). Poco soluble en frío', null, false),
  ('Disodium Cocoyl Glutamate', 'Cocoil glutamato de disodio', array['Tensioactivo limpiador', 'Espumante']::text[], null, '5-15%', 'Tensioactivo aniónico muy suave, derivado del coco y del ácido glutámico. Funciona a pH 5-6, cercano al de la piel, y da espuma cremosa.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'Incompatible con catiónicos', null, false),
  ('Sodium Cocoyl Glutamate', 'Cocoil glutamato de sodio', array['Tensioactivo limpiador', 'Espumante']::text[], null, '5-15%', 'Hermano del anterior: aniónico muy suave de coco y ácido glutámico. Ideal para rostro y piel sensible.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'Incompatible con catiónicos', null, false),
  ('Sodium Lauroyl Sarcosinate', 'Lauroil sarcosinato de sodio', array['Tensioactivo limpiador', 'Espumante']::text[], null, '5-15%', 'Tensioactivo aniónico de espuma abundante y buen poder limpiador, algo más suave que un sulfato.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'Puede irritar piel sensible', null, false),
  ('Sodium Lauryl Sulfoacetate', 'SLSA (lauril sulfoacetato de sodio)', array['Tensioactivo limpiador', 'Espumante']::text[], null, '10-40% en barras', 'Tensioactivo aniónico en polvo, de espuma abundante y algo más suave que un sulfato clásico. Se usa en barras y champús sólidos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'Incompatible con catiónicos', null, false),
  ('Sodium Coco-Sulfate', 'SCS (coco sulfato de sodio)', array['Tensioactivo limpiador', 'Espumante']::text[], null, '5-20%', 'Sulfato de origen coco. Espuma abundante y desengrasa bien: más potente y resecante que el SCI.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'Poco recomendable para piel sensible o seca', null, false),
  ('Sodium Lauryl Sulfate', 'SLS (lauril sulfato de sodio)', array['Tensioactivo limpiador', 'Espumante']::text[], null, 'Según la fórmula', 'Tensioactivo aniónico potente y económico. Espuma abundante y desengrasa mucho.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'Irritante: poco adecuado para piel o cuero cabelludo sensibles. No es "natural" aunque derive del coco', null, false),
  ('Sodium Laureth Sulfate', 'SLES (lauril éter sulfato de sodio)', array['Tensioactivo limpiador', 'Espumante']::text[], null, '5-15%', 'Sulfato etoxilado, más suave que el SLS. Base de muchos champús y geles de ducha convencionales.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'Puede contener trazas de 1,4-dioxano (subproducto del proceso)', null, false),
  ('Cocamidopropyl Betaine', 'Betaína de coco (cocamidopropil betaína)', array['Espumante', 'Tensioactivo limpiador']::text[], null, '3-10%', 'Tensioactivo anfótero. Da espuma, espesa con un poco de sal y suaviza a los aniónicos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'Trae trazas de impurezas que pueden sensibilizar a algunas personas', null, false),
  ('Coco-Betaine', 'Coco betaína', array['Espumante', 'Tensioactivo limpiador']::text[], null, '3-10%', 'Tensioactivo anfótero sin el grupo amido, más suave y con menos impurezas sensibilizantes que la cocamidopropil betaína.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', null, null, false),
  ('Disodium Cocoamphodiacetate', 'Cocoanfodiacetato de disodio', array['Tensioactivo limpiador', 'Espumante']::text[], null, '3-15%', 'Tensioactivo anfótero muy suave, que reduce la irritación de otros tensioactivos. Usado en productos para bebé y piel sensible.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', null, null, false),
  ('Sodium Cocoamphoacetate', 'Cocoanfoacetato de sodio', array['Tensioactivo limpiador', 'Espumante']::text[], null, '3-15%', 'Tensioactivo anfótero suave, buen compañero de los aniónicos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', null, null, false),
  ('Coco-Glucoside', 'Coco-glucósido', array['Tensioactivo limpiador', 'Espumante']::text[], null, '5-15%', 'Tensioactivo no iónico suave, hecho de azúcares y grasas del coco. Complementa a los aniónicos: mejora la espuma y reduce la irritación.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', null, null, false),
  ('Decyl Glucoside', 'Decil glucósido', array['Tensioactivo limpiador', 'Espumante']::text[], null, '5-20%', 'Tensioactivo no iónico muy suave, de azúcares y alcoholes grasos de coco. Aguanta bien el pH ácido y la piel sensible.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', null, null, false),
  ('Lauryl Glucoside', 'Lauril glucósido', array['Tensioactivo limpiador', 'Espumante']::text[], null, '5-20%', 'Tensioactivo no iónico suave, de espuma más estable que el decil glucósido.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', null, null, false),
  ('Caprylyl/Capryl Glucoside', 'Caprilil/capril glucósido', array['Tensioactivo limpiador', 'Solubilizante']::text[], null, '2-10%', 'Tensioactivo no iónico muy suave, de cadena corta. Solubiliza y refuerza conservantes.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', null, null, false),
  ('Sodium Methyl Cocoyl Taurate', 'Metil cocoil taurato de sodio', array['Tensioactivo limpiador', 'Espumante']::text[], null, '5-15%', 'Tensioactivo aniónico suave, de buena espuma y buen tacto. Funciona en agua dura.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'Incompatible con catiónicos', null, false),
  ('Sodium Lauroyl Methyl Isethionate', 'Lauroil metil isetionato de sodio', array['Tensioactivo limpiador', 'Espumante']::text[], null, '5-15%', 'Tensioactivo aniónico suave, tipo isetionato, de buena espuma y tolerancia.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'Incompatible con catiónicos', null, false),
  ('Sodium Olivate', 'Jabón de oliva (olivato de sodio)', array['Tensioactivo limpiador']::text[], null, 'Según la receta', 'Jabón obtenido saponificando aceite de oliva con soda cáustica. Base del jabón de Castilla: limpia y es suave, pero su pH es alcalino (~9-10).', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'pH alcalino: no es ideal para el rostro ni para el cuero cabelludo. La soda cáustica exige guantes, gafas y curado de 4-6 semanas', null, false),
  ('Sodium Cocoate', 'Jabón de coco (cocoato de sodio)', array['Tensioactivo limpiador', 'Espumante']::text[], null, 'Según la receta', 'Jabón de aceite de coco: espuma abundante, pero muy desengrasante y alcalino.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'pH alcalino', null, false),
  ('Sodium Tallowate', 'Jabón de sebo (tallowato de sodio)', array['Tensioactivo limpiador']::text[], null, 'Según la receta', 'Jabón obtenido saponificando sebo bovino. Da una barra dura, de espuma estable y buen tacto.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'pH alcalino; curado de 4-6 semanas', null, false),
  ('Sapindus Mukorossi Fruit Extract', 'Reetha (nuez de jabón)', array['Tensioactivo limpiador', 'Espumante']::text[], null, 'Según el preparado', 'Fruto rico en saponinas, tradicional en la India para lavar cabello y piel.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'Puede irritar los ojos', null, false),
  ('Sodium Lauroyl Lactylate', 'Lauroil lactilato de sodio', array['Emulsionante', 'Tensioactivo limpiador']::text[], null, '0.5-5%', 'Tensioactivo aniónico suave de origen vegetal que también actúa como emulsionante.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', null, null, false),
  ('Sodium Cocoyl Alaninate', 'Cocoil alaninato de sodio', array['Tensioactivo limpiador', 'Espumante']::text[], null, '5-15%', 'Tensioactivo aniónico suave, derivado de coco y del aminoácido alanina.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Tensioactivos y limpiadores', 'Incompatible con catiónicos', null, false),
  ('Piper Aduncum Leaf Extract', 'Matico', array['Astringente', 'Cicatrizante', 'Antimicrobiano']::text[], null, null, 'Piper aduncum (Piperaceae). Parte usada: hoja. Usos cosméticos tradicionales: Tónico reparador para pieles agredidas post-tratamiento; Activo en sérum cicatrizante para cicatrices y estrías; Calmante en formulaciones para pieles reactivas o atópicas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Evitar uso interno durante el embarazo por posible efecto emenagogo · Puede causar sensibilización en pieles muy sensibles — realizar prueba de parche · No usar en heridas profundas o punzantes sin supervisión médica · Interacción posible con anticoagulantes — consultar profesional · ATENCIÓN con la especie: en Chile "matico" suele ser Buddleja globosa (ver su fila aparte). Piper aduncum es el matico amazónico. Confirma cuál es la tuya antes de usar los estudios', 'hoja', false),
  ('Myrceugenia Exsucca Leaf Extract', 'Pitra', array['Astringente', 'Antimicrobiano']::text[], null, null, 'Myrceugenia exsucca (Myrtaceae). Parte usada: hoja. Usos cosméticos tradicionales: Tónico astringente para pieles grasas y poros dilatados; Activo antioxidante en sérum anti-aging; Agua de corteza en preparaciones para pieles acneicas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'No usar internamente por más de una semana continua por concentración de taninos · Puede interferir con la absorción de hierro y otros minerales · Evitar en estreñimiento crónico · Precaución en personas con úlcera gástrica activa', 'hoja', false),
  ('Luma Apiculata Leaf Extract', 'Arrayán', array['Astringente', 'Antioxidante']::text[], null, null, 'Luma apiculata (Myrtaceae). Parte usada: hoja. Usos cosméticos tradicionales: Aceite esencial en formulaciones antisépticas y desodorantes; Extracto en jabones antibacterianos artesanales; Agua floral de hojas en tónicos para pieles mixtas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Evitar aceite esencial puro sobre piel sin diluir (puede causar irritación) · Precaución en niños menores de 6 años con aceites esenciales · No usar internamente en cantidades elevadas — puede irritar la mucosa renal', 'hoja', false),
  ('Aristotelia Chilensis Fruit Extract', 'Maqui', array['Antioxidante', 'Colorante']::text[], null, null, 'Aristotelia chilensis (Elaeocarpaceae). Parte usada: fruto. Usos cosméticos tradicionales: Activo anti-aging en sérum por su acción sobre oxidación celular; Extracto en cremas fotoprotectoras naturales; Pigmento natural en cosmética color. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Puede potenciar efecto de anticoagulantes — consultar médico · Efecto hipoglucemiante: precaución en diabéticos con medicación · Los pigmentos tiñen piel y superficies — tomar precauciones · Los pigmentos (antocianinas) cambian de color con el pH y pueden teñir', 'fruto', false),
  ('Laureliopsis Philippiana Leaf Extract', 'Triwe', array['Astringente', 'Antimicrobiano']::text[], null, null, 'Laureliopsis philippiana (Atherospermataceae). Parte usada: hoja. Usos cosméticos tradicionales: Aceite esencial en aromaterapia de relajación; Extracto en cremas de masaje anticontractura; Activo sedante en formulaciones para pieles reactivas por estrés. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'No combinar con fármacos ansiolíticos o sedantes sin supervisión · Evitar durante el embarazo — posible efecto sobre útero · No usar antes de conducir o manejar maquinaria pesada · Uso prolongado puede generar tolerancia — ciclar el consumo · ATENCIÓN con la especie: en tus etiquetas el triwe figura como Laurelia sempervirens; esta ficha dice Laureliopsis philippiana (tepa). Confirma la especie con un botánico o con la guía de campo', 'hoja', false),
  ('Fuchsia Magellanica Leaf Extract', 'Chilco', array['Astringente', 'Calmante']::text[], null, null, 'Fuchsia magellanica (Onagraceae). Parte usada: hoja y flor. Usos cosméticos tradicionales: Tónico astringente para pieles con poros dilatados; Activo en fórmulas post-depilación calmantes; Extracto en contorno de ojos por su acción sobre microcirculación. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Uso interno prolongado puede causar estreñimiento por exceso de taninos · Evitar en personas con tendencia a estreñimiento crónico · Posible interferencia con absorción de fármacos — tomar con 2 h de diferencia', 'hoja y flor', false),
  ('Achillea Millefolium Extract', 'Milenrama', array['Astringente', 'Cicatrizante', 'Antiinflamatorio']::text[], null, null, 'Achillea millefolium (Asteraceae). Parte usada: sumidad florida. Usos cosméticos tradicionales: Activo antiinflamatorio en formulaciones para pieles sensibles; Extracto en cremas cicatrizantes post-acné; Tónico floral para pieles con rosácea o eritema facial. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Contraindicada en embarazo por su acción emenagoga · Puede causar dermatitis de contacto en personas sensibles a Asteráceas · Evitar con anticoagulantes — efecto hemostático puede interaccionar · No usar flores silvestres sin identificación segura — posible confusión con plantas tóxicas', 'sumidad florida', false),
  ('Peumus Boldus Leaf Extract', 'Boldo', array['Antioxidante', 'Astringente']::text[], null, null, 'Peumus boldus (Monimiaceae). Parte usada: hoja. Usos cosméticos tradicionales: Extracto antioxidante para pieles apagadas y grasas; Tónico purificante en formulaciones detox faciales; Agua aromática de hojas como astringente suave. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Contraindicado en embarazo y lactancia (el ascaridol puede ser abortivo) · No usar con obstrucción total de las vías biliares · Evitar el uso prolongado o en dosis altas — riesgo de toxicidad por ascaridol · Precaución con anticoagulantes y en enfermedad hepática grave · Contiene alcaloides (boldina) y ascaridol en el aceite esencial: no usar el aceite esencial', 'hoja', false),
  ('Haplopappus Baylahuen Extract', 'Bailahuén', array['Antiinflamatorio', 'Antimicrobiano']::text[], null, null, 'Haplopappus baylahuen (Asteraceae). Parte usada: hoja y flor. Usos cosméticos tradicionales: Extracto antioxidante y purificante para piel grasa; Tónico astringente por su contenido resinoso; Activo en formulaciones detox. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Evitar en embarazo y lactancia · No usar con obstrucción de las vías biliares · Puede causar dermatitis de contacto en sensibles a Asteráceas · Uso en curas cortas, no prolongado', 'hoja y flor', false),
  ('Drimys Winteri Bark Extract', 'Canelo · Foye', array['Antimicrobiano', 'Astringente', 'Antiinflamatorio']::text[], null, null, 'Drimys winteri (Winteraceae). Parte usada: corteza y hoja. Usos cosméticos tradicionales: Activo cicatrizante y antioxidante (vitamina C natural); Extracto antimicrobiano para pieles con tendencia acneica; Tónico de corteza para pieles agredidas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Evitar el uso interno en embarazo y lactancia · En dosis altas la corteza puede ser irritante del tracto digestivo · Realizar prueba de parche antes del uso tópico extendido · Respetar su carácter de planta sagrada — usar con atribución cultural', 'corteza y hoja', false),
  ('Plantago Major Leaf Extract', 'Llantén', array['Calmante', 'Cicatrizante', 'Astringente']::text[], null, null, 'Plantago major (Plantaginaceae). Parte usada: hoja. Usos cosméticos tradicionales: Activo cicatrizante y calmante (alantoína natural); Extracto para pieles sensibles, reactivas o irritadas; Tónico astringente suave para pieles mixtas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Muy bien tolerado; raras reacciones alérgicas · Recolectar lejos de caminos y zonas contaminadas (acumula metales) · Moderar el uso interno prolongado por su contenido de taninos · Prueba de parche antes del uso tópico extendido en piel muy reactiva', 'hoja', false),
  ('Chenopodium Ambrosioides Extract', 'Paico', array['Antimicrobiano']::text[], null, null, 'Dysphania ambrosioides (Amaranthaceae). Parte usada: hoja y sumidad. Usos cosméticos tradicionales: Uso cosmético muy limitado por la toxicidad del aceite esencial; Eventual extracto antimicrobiano a muy baja concentración. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Contraindicado en embarazo y lactancia (abortivo) · No usar en niños pequeños · Tóxico en dosis altas o uso prolongado (ascaridol neuro y hepatotóxico) · Nunca usar el aceite esencial puro por vía interna · Contiene ascaridol, tóxico: no usar aceite esencial ni uso interno. En cosmética, solo extractos externos y con prudencia', 'hoja y sumidad', false),
  ('Rosa Rubiginosa Fruit Extract', 'Rosa Mosqueta', array['Antioxidante', 'Regenerador']::text[], null, null, 'Rosa rubiginosa (Rosaceae). Parte usada: escaramujo (fruto). Usos cosméticos tradicionales: Aceite antiedad para piel madura — estimula el colágeno; Atenúa estrías, cicatrices y manchas; Activo reparador en sérums y aceites faciales. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'El aceite se oxida (enrancia) con facilidad — conservar en frío y oscuridad · En pieles muy grasas o acneicas puede resultar comedogénico en exceso · Realizar prueba de parche en pieles reactivas · No exponer el aceite a calor alto (degrada el retinoico y los omega) · El aceite de la semilla está en la categoría Aceites vegetales', 'escaramujo (fruto)', false),
  ('Chamomilla Recutita Flower Extract', 'Manzanilla', array['Calmante', 'Antiinflamatorio']::text[], null, null, 'Matricaria chamomilla (Asteraceae). Parte usada: flor. Usos cosméticos tradicionales: Activo calmante para pieles sensibles, reactivas y con rojeces; Agua floral (hidrolato) como tónico suave y descongestivo; Extracto para contorno de ojos y pieles delicadas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Posible alergia en personas sensibles a las Asteráceas (margaritas) · En dosis muy altas puede ser emética · Precaución con anticoagulantes (contenido de cumarinas) · Prueba de parche antes del uso tópico en piel muy reactiva', 'flor', false),
  ('Equisetum Arvense Extract', 'Cola de Caballo', array['Astringente', 'Fortalecedor capilar']::text[], null, null, 'Equisetum arvense (Equisetaceae). Parte usada: tallo estéril. Usos cosméticos tradicionales: Reafirmante y antiedad — estimula el colágeno y la elastina; Fortalecedor de cabello y uñas (silicio); Astringente para pieles grasas y poros dilatados. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'No usar en edemas por insuficiencia cardíaca o renal grave · El uso prolongado puede reducir la tiamina (vitamina B1) — hacer curas cortas · Evitar en embarazo y lactancia · Identificar bien la especie: no confundir con Equisetum palustre (tóxico)', 'tallo estéril', false),
  ('Melissa Officinalis Leaf Extract', 'Toronjil · Melisa', array['Calmante', 'Antimicrobiano']::text[], null, null, 'Melissa officinalis (Lamiaceae). Parte usada: hoja. Usos cosméticos tradicionales: Activo antioxidante y calmante para pieles reactivas; Agua floral (hidrolato) como tónico refrescante; Extracto antiviral en bálsamos labiales. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'En dosis altas puede afectar la función tiroidea — precaución en hipotiroidismo · Puede potenciar sedantes y ansiolíticos · Evitar dosis altas en embarazo · Somnolencia: precaución al conducir tras dosis altas', 'hoja', false),
  ('Mentha Piperita Leaf Extract', 'Menta', array['Refrescante', 'Antipruriginoso']::text[], null, null, 'Mentha × piperita (Lamiaceae). Parte usada: hoja. Usos cosméticos tradicionales: Activo refrescante en cremas de piernas cansadas y pies; Tónico purificante para pieles grasas; Aroma y frescor en pasta dental y bálsamos labiales. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'No aplicar mentol ni aceite esencial en la cara de bebés y niños pequeños (riesgo de espasmo laríngeo) · Puede agravar el reflujo gastroesofágico (relaja el esfínter esofágico) · Evitar el aceite esencial puro sobre la piel sin diluir · Precaución en cálculos biliares y hernia de hiato', 'hoja', false),
  ('Rosmarinus Officinalis Leaf Extract', 'Romero', array['Antioxidante', 'Estimulante']::text[], null, null, 'Salvia rosmarinus (Lamiaceae). Parte usada: hoja. Usos cosméticos tradicionales: Tónico capilar anticaída — estimula el folículo y el riego del cuero cabelludo; Antioxidante antiedad en sérums y cremas; Astringente y purificante para pieles grasas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Evitar dosis altas en embarazo (emenagogo) · Precaución en epilepsia por el alcanfor del aceite esencial · Dosis altas pueden elevar la presión arterial · No aplicar el aceite esencial puro sobre la piel', 'hoja', false),
  ('Thymus Vulgaris Extract', 'Tomillo', array['Antimicrobiano', 'Antioxidante']::text[], null, null, 'Thymus vulgaris (Lamiaceae). Parte usada: hoja y flor. Usos cosméticos tradicionales: Antimicrobiano en formulaciones para piel acneica; Tónico purificante del cuero cabelludo (caspa); Conservante natural suave por su poder antimicrobiano. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'El aceite esencial es dermocáustico (timol/carvacrol) — máximo 0.5–1%, nunca puro · Evitar dosis altas en embarazo y lactancia · Precaución en hipertensión (dosis altas del AE) · No usar el aceite esencial en niños pequeños', 'hoja y flor', false),
  ('Origanum Vulgare Leaf Extract', 'Orégano', array['Antimicrobiano', 'Antioxidante']::text[], null, null, 'Origanum vulgare (Lamiaceae). Parte usada: hoja. Usos cosméticos tradicionales: Antimicrobiano potente en formulaciones antiacné (muy diluido); Antifúngico en preparaciones para pie de atleta; Conservante natural por su poder antimicrobiano. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'El aceite esencial es dermocáustico — nunca puro, máximo 0.5% · Evitar en embarazo (emenagogo en dosis altas) · Puede irritar mucosas en dosis altas · Precaución con anticoagulantes', 'hoja', false),
  ('Urtica Dioica Leaf Extract', 'Ortiga', array['Astringente', 'Seborregulador', 'Fortalecedor capilar']::text[], null, null, 'Urtica dioica (Urticaceae). Parte usada: hoja. Usos cosméticos tradicionales: Tónico capilar anticaída y contra la caspa — clásico del pelo fuerte; Seborregulador del cuero cabelludo y de pieles grasas; Remineralizante y astringente en tónicos faciales. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Manipular fresca con guantes (pelos urticantes) · Diurético: precaución con edemas por insuficiencia cardíaca o renal grave · Puede potenciar hipotensores y antidiabéticos · Evitar dosis altas en embarazo', 'hoja', false),
  ('Taraxacum Officinale Extract', 'Diente de León', array['Antioxidante', 'Calmante']::text[], null, null, 'Taraxacum officinale (Asteraceae). Parte usada: hoja y raíz. Usos cosméticos tradicionales: Extracto depurativo y antioxidante para pieles congestionadas; Activo detox en formulaciones faciales; Tónico para pieles apagadas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'No usar con obstrucción de las vías biliares · Precaución en cálculos biliares (efecto colagogo) · Posible alergia en sensibles a las Asteráceas · Puede potenciar diuréticos y antidiabéticos', 'hoja y raíz', false),
  ('Calendula Officinalis Flower Extract', 'Caléndula', array['Calmante', 'Antiinflamatorio', 'Cicatrizante']::text[], null, null, 'Calendula officinalis (Asteraceae). Parte usada: flor. Usos cosméticos tradicionales: Oleato y bálsamo reparador para pieles sensibles y atópicas; Activo calmante en cremas para bebé y pieles reactivas; Agua floral (hidrolato) como tónico suave. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Posible alergia en sensibles a las Asteráceas (margaritas) · Evitar el uso interno en embarazo (emenagogo en dosis altas) · Prueba de parche antes del uso tópico extendido en piel muy reactiva · Uso interno con moderación; su fuerte es el uso tópico · Probar en el antebrazo antes de usar si eres sensible a las asteráceas', 'flor', false),
  ('Hypericum Perforatum Extract', 'Hipérico · Hierba de San Juan', array['Calmante', 'Antiinflamatorio']::text[], null, null, 'Hypericum perforatum (Hypericaceae). Parte usada: sumidad florida. Usos cosméticos tradicionales: Oleato rojo reparador para pieles agredidas; Activo antiinflamatorio y calmante en bálsamos; Cuidado post-solar (solo de noche, por la fotosensibilidad). Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'FUERTE fotosensibilizante — no exponer la piel tratada al sol · Numerosas interacciones: anula anticonceptivos orales; con antidepresivos ISRS puede dar síndrome serotoninérgico; afecta anticoagulantes, inmunosupresores y antirretrovirales · No combinar con ningún medicamento sin consultar (induce el CYP3A4) · Evitar en embarazo y lactancia · Fotosensibilizante: evita el sol tras aplicarlo. Interactúa con medicamentos si se usa por vía interna', 'sumidad florida', false),
  ('Salix Alba Bark Extract', 'Sauce Blanco', array['Astringente', 'Queratolítico']::text[], null, null, 'Salix alba (Salicaceae). Parte usada: corteza. Usos cosméticos tradicionales: Exfoliante BHA natural (salicina) para piel grasa y acneica; Astringente y seborregulador; Activo suave para destapar poros. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Contraindicado en alergia a la aspirina y los salicilatos · No dar a niños con fiebre viral (riesgo de síndrome de Reye) · Evitar en embarazo, lactancia y úlcera gástrica · Precaución con anticoagulantes · Contiene salicina (precursor de salicilatos): evitar si hay alergia a la aspirina o a los salicilatos', 'corteza', false),
  ('Sambucus Nigra Flower Extract', 'Saúco', array['Astringente', 'Calmante']::text[], null, null, 'Sambucus nigra (Adoxaceae). Parte usada: flor. Usos cosméticos tradicionales: Agua de flores de saúco como tónico suavizante y aclarante; Activo antioxidante (bayas) en cosmética antiedad; Calmante para pieles sensibles. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Tallos, hojas y bayas crudas son tóxicos (glucósidos cianogénicos) — cocer siempre las bayas · Usar solo la flor y la baya madura y cocida · Precaución con diuréticos y en embarazo · No confundir con especies de Sambucus de bayas rojas (más tóxicas)', 'flor', false),
  ('Valeriana Officinalis Root Extract', 'Valeriana', array['Calmante']::text[], null, null, 'Valeriana officinalis (Caprifoliaceae). Parte usada: raíz. Usos cosméticos tradicionales: Uso cosmético limitado por su aroma intenso; Aromaterapia de relajación en brumas de ambiente. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Produce somnolencia — no conducir ni operar maquinaria tras tomarla · Potencia el alcohol, los sedantes y los ansiolíticos · Evitar en embarazo y lactancia · Uso prolongado puede generar tolerancia — ciclar el consumo · Olor fuerte y desagradable', 'raíz', false),
  ('Lavandula Angustifolia Flower Extract', 'Lavanda', array['Calmante', 'Antimicrobiano']::text[], null, null, 'Lavandula angustifolia (Lamiaceae). Parte usada: flor. Usos cosméticos tradicionales: Calmante y regenerante para pieles sensibles y con acné; Agua floral (hidrolato) como tónico equilibrante; Activo aromaterapéutico en cremas y brumas relajantes. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Dosis altas por vía interna pueden causar somnolencia · Precaución con el aceite esencial en el primer trimestre del embarazo · Realizar prueba de parche en pieles muy reactivas · El aceite esencial de lavandín (híbrido) es más alcanforado — no confundir', 'flor', false),
  ('Aloe Barbadensis Leaf Juice', 'Aloe Vera', array['Humectante', 'Calmante', 'Cicatrizante']::text[], null, null, 'Aloe barbadensis (Asphodelaceae). Parte usada: hoja (gel). Usos cosméticos tradicionales: Gel base hidratante y calmante para todo tipo de piel; After-sun y mascarillas refrescantes; Vehículo acuoso ligero para otros activos. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'El látex/acíbar (laxante) está contraindicado en embarazo, lactancia y niños · No usar el látex de forma prolongada — irrita el intestino · El gel fresco se contamina en días: refrigerar y conservar · Lavar bien el gel para eliminar restos de látex amarillo · El látex amarillo de la corteza es irritante: usar solo el gel interior', 'hoja (gel)', false),
  ('Hamamelis Virginiana Leaf Extract', 'Hamamelis', array['Astringente', 'Tonificante']::text[], null, null, 'Hamamelis virginiana (Hamamelidaceae). Parte usada: hoja y corteza. Usos cosméticos tradicionales: Tónico astringente para pieles grasas y poros dilatados; Descongestivo del contorno de ojos (bolsas); After-shave calmante y astringente. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Uso interno prolongado no recomendado por su alta concentración de taninos · Puede resecar en exceso las pieles muy secas · Los preparados con alcohol pueden irritar pieles sensibles · Prueba de parche antes del uso extendido · Los comerciales traen alcohol: puede resecar', 'hoja y corteza', false),
  ('Arnica Montana Flower Extract', 'Árnica', array['Antiinflamatorio']::text[], null, null, 'Arnica montana (Asteraceae). Parte usada: flor. Usos cosméticos tradicionales: Oleato o gel para golpes y piernas cansadas; Activo descongestivo en preparaciones de masaje; No usar en pieles con acné activo o heridas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'SOLO uso externo sobre piel sana — tóxico por vía interna · No aplicar sobre heridas abiertas, mucosas ni piel dañada · Puede causar dermatitis; alergia frecuente en sensibles a Asteráceas · No usar en embarazo ni de forma prolongada · Solo sobre piel íntegra. Puede sensibilizar; evitar en heridas abiertas', 'flor', false),
  ('Foeniculum Vulgare Fruit Extract', 'Hinojo', array['Calmante', 'Descongestionante']::text[], null, null, 'Foeniculum vulgare (Apiaceae). Parte usada: fruto (semilla). Usos cosméticos tradicionales: Tónico descongestivo del contorno de ojos; Agua aromática digestiva y refrescante; Activo en formulaciones reafirmantes. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'El anetol es fitoestrógeno — precaución en cáncer hormonodependiente y endometriosis · El aceite esencial no debe usarse en embarazo, epilepsia ni en niños pequeños · Usar en dosis culinarias-terapéuticas moderadas · Posible alergia en sensibles a las Apiáceas', 'fruto (semilla)', false),
  ('Pimpinella Anisum Fruit Extract', 'Anís', array['Antimicrobiano']::text[], null, null, 'Pimpinella anisum (Apiaceae). Parte usada: fruto (semilla). Usos cosméticos tradicionales: Aromatizante natural de bálsamos labiales y pastas dentales; Agua aromática digestiva. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'El anetol es fitoestrógeno — precaución en tumores hormonodependientes · El aceite esencial no se usa en embarazo ni en niños pequeños · Posible alergia en sensibles a las Apiáceas · No confundir con el anís estrellado japonés (tóxico)', 'fruto (semilla)', false),
  ('Silybum Marianum Seed Extract', 'Cardo Mariano', array['Antioxidante']::text[], null, null, 'Silybum marianum (Asteraceae). Parte usada: semilla (fruto). Usos cosméticos tradicionales: El aceite de sus semillas es antioxidante y regenerante para la piel; Activo protector frente al estrés oxidativo cutáneo. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Posible alergia en sensibles a las Asteráceas · Puede alterar el metabolismo de algunos fármacos (consultar) · Evitar con obstrucción de las vías biliares · Efecto laxante leve en dosis altas', 'semilla (fruto)', false),
  ('Echinacea Purpurea Extract', 'Equinácea', array['Calmante', 'Antimicrobiano']::text[], null, null, 'Echinacea purpurea (Asteraceae). Parte usada: hierba y raíz. Usos cosméticos tradicionales: Activo cicatrizante y regenerante para pieles dañadas; Antiinflamatorio para pieles sensibles; Extracto reparador en cremas antiedad. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Contraindicada en enfermedades autoinmunes (estimula el sistema inmune) · Usar en ciclos cortos, no de forma continua prolongada · Posible alergia en sensibles a las Asteráceas · Precaución con inmunosupresores', 'hierba y raíz', false),
  ('Zingiber Officinale Root Extract', 'Jengibre', array['Estimulante', 'Antioxidante']::text[], null, null, 'Zingiber officinale (Zingiberaceae). Parte usada: rizoma. Usos cosméticos tradicionales: Estimulante de la circulación del cuero cabelludo (anticaída); Antioxidante en cosmética antiedad; Activo calorífico en preparaciones de masaje. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Precaución en cálculos biliares (colagogo) · Efecto antiagregante — cuidado con anticoagulantes y antes de cirugías · Dosis altas pueden agravar el reflujo y la úlcera · Moderar en embarazo (dosis culinarias son seguras)', 'rizoma', false),
  ('Curcuma Longa Root Extract', 'Cúrcuma', array['Antioxidante', 'Colorante']::text[], null, null, 'Curcuma longa (Zingiberaceae). Parte usada: rizoma. Usos cosméticos tradicionales: Antiinflamatoria y antioxidante en mascarillas faciales; Iluminadora y unificadora del tono (mascarillas); Activo antiacné por su acción antibacteriana. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Precaución en cálculos y obstrucción de las vías biliares (colagoga) · Efecto antiagregante — cuidado con anticoagulantes y antes de cirugías · Puede teñir la piel, uñas y ropa de amarillo · Moderar dosis altas en embarazo · Mancha piel, telas y lavamanos', 'rizoma', false),
  ('Quillaja Saponaria Bark Extract', 'Quillay', array['Espumante', 'Tensioactivo limpiador']::text[], null, null, 'Quillaja saponaria (Quillajaceae). Parte usada: corteza. Usos cosméticos tradicionales: Champú y limpiador facial natural, sin sulfatos (saponinas); Tensioactivo suave para syndets y jabones líquidos artesanales; Control de la caspa y el exceso de grasa del cuero cabelludo. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Las saponinas irritan los ojos y las mucosas — evitar el contacto · No usar por vía interna en dosis altas (las saponinas son hemolíticas) · El polvo de corteza irrita las vías respiratorias — usar mascarilla al manipularlo · No aplicar en heridas profundas ni piel muy dañada · Irrita los ojos y mucosas', 'corteza', false),
  ('Fabiana Imbricata Extract', 'Pichi-romero', array['Antimicrobiano']::text[], null, null, 'Fabiana imbricata (Solanaceae). Parte usada: ramas y hojas. Usos cosméticos tradicionales: Extracto depurativo para pieles congestionadas (uso limitado). Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Es una solanácea — no usar en dosis altas ni de forma prolongada · Evitar en embarazo y lactancia · No usar en insuficiencia renal grave · Respetar las dosis: en exceso puede ser irritante', 'ramas y hojas', false),
  ('Quinchamalium Chilense Extract', 'Quinchamalí', array['Astringente']::text[], null, null, 'Quinchamalium chilense (Schoepfiaceae). Parte usada: planta entera. Usos cosméticos tradicionales: Activo para pieles con capilares marcados y varículas; Descongestivo en preparaciones para piernas cansadas; Oleato para masaje descongestivo. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Uso principalmente tradicional — poca evidencia clínica · Precaución en embarazo y lactancia · Realizar prueba de parche antes del uso tópico extendido · Recolección responsable: es una especie nativa presionada', 'planta entera', false),
  ('Centaurium Cachanlahuen Extract', 'Canchalagua · Cachanlagua', array['Tonificante']::text[], null, null, 'Centaurium cachanlahuen (Gentianaceae). Parte usada: sumidad florida. Usos cosméticos tradicionales: Extracto depurativo para pieles con acné y granos; Tónico purificante para pieles grasas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Los amargos estimulan la secreción gástrica — evitar en úlcera gástrica activa · Evitar dosis altas en embarazo · Su sabor muy amargo puede provocar náuseas en personas sensibles · Usar en curas cortas, no de forma prolongada', 'sumidad florida', false),
  ('Lomatia Hirsuta Leaf Extract', 'Radal', array['Astringente']::text[], null, null, 'Lomatia hirsuta (Proteaceae). Parte usada: hoja. Usos cosméticos tradicionales: Uso cosmético limitado; eventual extracto en preparaciones respiratorias de vapor. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Uso principalmente tradicional — dosificar con prudencia · Evitar en embarazo y lactancia por precaución · No superar las dosis habituales · Recolección responsable de una especie nativa', 'hoja', false),
  ('Eucryphia Cordifolia Extract', 'Ulmo', array['Astringente', 'Antimicrobiano']::text[], null, null, 'Eucryphia cordifolia (Cunoniaceae). Parte usada: corteza y hoja. Usos cosméticos tradicionales: Extracto astringente y cicatrizante de corteza; La miel de ulmo en mascarillas nutritivas y antibacterianas; Activo reparador para pieles agredidas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Uso interno prolongado no recomendado por su alto contenido de taninos · Realizar prueba de parche antes del uso tópico extendido · La miel no debe darse a menores de 1 año (riesgo de botulismo infantil) · Recolección responsable de la corteza para no dañar el árbol', 'corteza y hoja', false),
  ('Maytenus Boaria Leaf Extract', 'Maitén', array['Calmante', 'Astringente']::text[], null, null, 'Maytenus boaria (Celastraceae). Parte usada: hoja. Usos cosméticos tradicionales: Enjuague capilar para el cuero cabelludo; Lavados y compresas para pieles irritadas; Extracto astringente suave. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Uso principalmente tradicional — dosificar con prudencia · Evitar dosis altas en embarazo · En exceso puede tener efecto laxante · No confundir con otras especies del género', 'hoja', false),
  ('Cryptocarya Alba Leaf Extract', 'Peumo', array['Astringente']::text[], null, null, 'Cryptocarya alba (Lauraceae). Parte usada: hoja. Usos cosméticos tradicionales: Baños y lavados astringentes para la piel; Extracto tónico para pieles grasas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Uso principalmente tradicional — dosificar con prudencia · Evitar en embarazo y lactancia por precaución · Los frutos se consumen solo cocidos · No superar las dosis habituales', 'hoja', false),
  ('Otholobium Glandulosum Leaf Extract', 'Culén', array['Antimicrobiano']::text[], null, null, 'Otholobium glandulosum (Fabaceae). Parte usada: hoja. Usos cosméticos tradicionales: Extracto cicatrizante y antiséptico; Uso externo en preparaciones para la piel. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Contiene furanocumarinas fotosensibilizantes — no exponer al sol la piel tratada · Evitar dosis altas en embarazo · Uso en dosis moderadas · Uso principalmente tradicional · Pertenece a un grupo (Psoralea s.l.) con especies fotosensibilizantes por psoralenos; no está verificado en esta especie. Prueba de parche y evita el sol', 'hoja', false),
  ('Gunnera Tinctoria Leaf Extract', 'Nalca · Pangue', array['Astringente', 'Antiinflamatorio']::text[], null, null, 'Gunnera tinctoria (Gunneraceae). Parte usada: hoja. Usos cosméticos tradicionales: Astringente y tensor para pieles grasas y poros dilatados; Tónico facial por su contenido de taninos; Activo en formulaciones purificantes. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Uso interno prolongado no recomendado por su alto contenido de taninos · Identificar bien la planta antes de recolectar · Los taninos pueden interferir con la absorción de hierro · Prueba de parche antes del uso tópico extendido', 'hoja', false),
  ('Allium Sativum Bulb Extract', 'Ajo', array['Antimicrobiano']::text[], null, null, 'Allium sativum (Amaryllidaceae). Parte usada: bulbo. Usos cosméticos tradicionales: Antifúngico en preparaciones para uñas (muy diluido); Tónico capilar estimulante (con precaución por el olor y la irritación); Antibacteriano puntual en acné (nunca puro). Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Efecto antiagregante — cuidado con anticoagulantes y antes de cirugías · Irrita la mucosa gástrica: precaución en gastritis y reflujo · El ajo crudo sobre la piel puede causar quemaduras — nunca puro · Puede alterar el sabor de la leche materna en la lactancia · Irritante sobre la piel; olor persistente', 'bulbo', false),
  ('Allium Cepa Bulb Extract', 'Cebolla', array['Antimicrobiano']::text[], null, null, 'Allium cepa (Amaryllidaceae). Parte usada: bulbo. Usos cosméticos tradicionales: Extracto para atenuar cicatrices y queloides; Tónico capilar anticaída (estimula el folículo); Activo antioxidante (quercetina). Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Irrita la mucosa gástrica: precaución en reflujo y gastritis · La cebolla fresca sobre la piel puede irritar — usar el extracto, no el bulbo crudo · Efecto antiagregante leve — cuidado con anticoagulantes · Puede producir gases y molestias digestivas en dosis altas · Puede irritar piel y ojos', 'bulbo', false),
  ('Coriandrum Sativum Extract', 'Cilantro', array['Antioxidante']::text[], null, null, 'Coriandrum sativum (Apiaceae). Parte usada: hoja y fruto. Usos cosméticos tradicionales: Extracto detox y antioxidante para pieles congestionadas; Aromatizante fresco natural. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Posible alergia en sensibles a las Apiáceas · El aceite esencial puede fotosensibilizar en dosis altas · Moderar en embarazo (dosis culinarias son seguras) · En algunas personas el sabor resulta jabonoso (genético)', 'hoja y fruto', false),
  ('Cinnamomum Zeylanicum Bark Extract', 'Canela', array['Antimicrobiano', 'Estimulante']::text[], null, null, 'Cinnamomum verum (Lauraceae). Parte usada: corteza. Usos cosméticos tradicionales: Estimulante de la circulación (labios, cuero cabelludo) — muy diluido; Aromatizante cálido natural; Antimicrobiano en formulaciones (con mucha precaución). Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Preferir canela de Ceilán: la casia contiene mucha cumarina (tóxica para el hígado en exceso) · El aceite esencial es dermocáustico — nunca puro, máximo 0.05% en enjuague · Evitar dosis medicinales altas en embarazo · Precaución con hipoglucemiantes (potencia el efecto) y en úlcera · Contiene cinamaldehído, sensibilizante: dosis bajas y prueba de parche', 'corteza', false),
  ('Piper Nigrum Fruit Extract', 'Pimienta Negra', array['Estimulante']::text[], null, null, 'Piper nigrum (Piperaceae). Parte usada: fruto. Usos cosméticos tradicionales: Potenciador de la penetración de activos en formulaciones; Estimulante circulatorio (muy diluido). Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Irrita la mucosa en dosis altas — precaución en úlcera y reflujo · La piperina altera el metabolismo de varios fármacos (consultar) · El aceite esencial es irritante — usar muy diluido · Moderar dosis medicinales en embarazo · Efecto rubefaciente: puede enrojecer y arder en piel sensible', 'fruto', false),
  ('Camellia Sinensis Leaf Extract', 'Té Verde', array['Antioxidante', 'Astringente']::text[], null, null, 'Camellia sinensis (Theaceae). Parte usada: hoja. Usos cosméticos tradicionales: Antioxidante y antiedad en sérums y cremas; Seborregulador y antiacneico para pieles grasas; Descongestivo del contorno de ojos (compresas). Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Contiene cafeína — moderar en insomnio, ansiedad y embarazo · Los taninos reducen la absorción de hierro — separar de las comidas · Precaución con anticoagulantes (dosis muy altas) · En ayunas puede causar acidez en personas sensibles', 'hoja', false),
  ('Ginkgo Biloba Leaf Extract', 'Ginkgo', array['Antioxidante']::text[], null, null, 'Ginkgo biloba (Ginkgoaceae). Parte usada: hoja. Usos cosméticos tradicionales: Activo microcirculatorio en cremas antiedad y contorno de ojos; Antioxidante protector; Estimulante del riego del cuero cabelludo. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Efecto antiagregante — riesgo de hemorragia con anticoagulantes y antes de cirugías · Evitar en embarazo y lactancia · Precaución en epilepsia · La semilla y la pulpa cruda son tóxicas — solo se usa la hoja', 'hoja', false),
  ('Panax Ginseng Root Extract', 'Ginseng', array['Antioxidante', 'Estimulante']::text[], null, null, 'Panax ginseng (Araliaceae). Parte usada: raíz. Usos cosméticos tradicionales: Revitalizante y antiedad (mejora la microcirculación de la piel); Tónico para pieles apagadas y fatigadas; Activo energizante en sérums. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Evitar en hipertensión no controlada · Puede causar insomnio y nerviosismo — no tomar por la noche · Evitar en embarazo y lactancia · Precaución con anticoagulantes, hipoglucemiantes y otros estimulantes; usar en ciclos', 'raíz', false),
  ('Withania Somnifera Root Extract', 'Ashwagandha', array['Antioxidante']::text[], null, null, 'Withania somnifera (Solanaceae). Parte usada: raíz. Usos cosméticos tradicionales: Antioxidante ''antiestrés'' para la piel; Activo revitalizante en cosmética adaptógena. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Es una solanácea; evitar en embarazo (puede ser abortiva en dosis altas) · Precaución en hipertiroidismo (puede estimular la tiroides) · Evitar en enfermedades autoinmunes sin supervisión · Puede potenciar sedantes y ansiolíticos · Solanácea: uso tópico con prueba de parche', 'raíz', false),
  ('Glycyrrhiza Glabra Root Extract', 'Regaliz', array['Calmante', 'Aclarante', 'Antiinflamatorio']::text[], null, null, 'Glycyrrhiza glabra (Fabaceae). Parte usada: raíz. Usos cosméticos tradicionales: Despigmentante suave para manchas y unificar el tono; Antiinflamatorio y calmante para pieles sensibles y con rojeces; Activo para dermatitis y eccemas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'La glicirricina SUBE la presión arterial y retiene sodio — contraindicado en hipertensión · No usar de forma prolongada (riesgo de bajar el potasio) · Evitar en embarazo, enfermedad renal y con corticoides o diuréticos · Para uso interno prolongado, preferir regaliz desglicirrizinado (DGL)', 'raíz', false),
  ('Ocimum Basilicum Leaf Extract', 'Albahaca', array['Antimicrobiano', 'Antioxidante']::text[], null, null, 'Ocimum basilicum (Lamiaceae). Parte usada: hoja. Usos cosméticos tradicionales: Antibacteriano en formulaciones para piel acneica; Tónico purificante para piel grasa; Aroma fresco natural. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'El aceite esencial contiene estragol — evitar en dosis altas y en embarazo · No usar el aceite esencial puro sobre la piel · Moderar el uso medicinal en embarazo y lactancia · Posible sensibilización en pieles muy reactivas', 'hoja', false),
  ('Salvia Officinalis Leaf Extract', 'Salvia', array['Astringente', 'Antimicrobiano']::text[], null, null, 'Salvia officinalis (Lamiaceae). Parte usada: hoja. Usos cosméticos tradicionales: Antisudoral en desodorantes naturales; Astringente y seborregulador para piel grasa; Tónico capilar (caspa y cabello graso; oscurece las canas). Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Contiene tuyona (neurotóxica en exceso): no usar en dosis altas ni de forma prolongada · Corta la producción de leche — evitar en lactancia (salvo al destetar) · Evitar en embarazo y en epilepsia · No usar el aceite esencial puro por vía interna · Contiene tuyona: no usar el aceite esencial en embarazo', 'hoja', false),
  ('Ruta Graveolens Extract', 'Ruda', array['Antimicrobiano']::text[], null, null, 'Ruta graveolens (Rutaceae). Parte usada: hoja. Usos cosméticos tradicionales: Uso cosmético muy limitado por su toxicidad y fotosensibilidad. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'ABORTIVA — contraindicada de forma absoluta en el embarazo · Tóxica en dosis altas (daño hepático y renal) · Fotosensibilizante potente — provoca quemaduras y dermatitis con el sol · No usar por vía interna sin supervisión profesional · FOTOSENSIBILIZANTE (furocumarinas) y puede causar quemaduras con el sol. Uso cosmético no recomendado', 'hoja', false),
  ('Malva Sylvestris Flower Extract', 'Malva', array['Calmante', 'Humectante']::text[], null, null, 'Malva sylvestris (Malvaceae). Parte usada: flor y hoja. Usos cosméticos tradicionales: Calmante para pieles sensibles, secas e irritadas; Mucílagos suavizantes en mascarillas; Tónico emoliente. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Muy bien tolerada; contraindicaciones prácticamente nulas · Puede reducir la absorción de otros medicamentos — tomar por separado · Recolectar en zonas limpias, lejos de la contaminación · Prueba de parche antes del uso tópico en piel muy reactiva', 'flor y hoja', false),
  ('Borago Officinalis Flower Extract', 'Borraja', array['Calmante']::text[], null, null, 'Borago officinalis (Boraginaceae). Parte usada: flor. Usos cosméticos tradicionales: Aceite de borraja para pieles secas, maduras y atópicas (GLA); Regenerador de la barrera cutánea; Activo antiedad y nutritivo. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'La PLANTA (hojas) contiene alcaloides pirrolizidínicos hepatotóxicos — no usar internamente de forma prolongada · El ACEITE de semillas está libre de esos alcaloides y es seguro · Evitar el uso interno de la hoja en embarazo, lactancia y enfermedad hepática · El aceite se oxida — conservar refrigerado · Las hojas contienen alcaloides pirrolizidínicos: no usar la planta entera de forma prolongada', 'flor', false),
  ('Aloysia Citrodora Leaf Extract', 'Cedrón · Hierba Luisa', array['Calmante', 'Antioxidante']::text[], null, null, 'Aloysia citriodora (Verbenaceae). Parte usada: hoja. Usos cosméticos tradicionales: Agua aromática tónica y refrescante; Aroma cítrico natural en cosmética; Calmante para pieles reactivas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Bien tolerado; el aceite esencial (citral) puede fotosensibilizar en dosis altas · Moderar en embarazo · No usar el aceite esencial puro sobre la piel · Puede bajar levemente la presión en dosis altas', 'hoja', false),
  ('Mentha Pulegium Extract', 'Poleo', array['Antimicrobiano']::text[], null, null, 'Mentha pulegium (Lamiaceae). Parte usada: hoja. Usos cosméticos tradicionales: Uso cosmético muy limitado por la toxicidad de su aceite esencial. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'El ACEITE ESENCIAL (pulegona) es hepatotóxico y abortivo — NUNCA usarlo · Contraindicado en embarazo, incluso en infusión · No usar en niños pequeños ni en enfermedad hepática · Solo infusión suave de la hoja, en dosis moderadas · Contiene pulegona (tóxica): no usar aceite esencial y evitar en embarazo', 'hoja', false),
  ('Mentha Spicata Leaf Extract', 'Hierba Buena', array['Refrescante']::text[], null, null, 'Mentha spicata (Lamiaceae). Parte usada: hoja. Usos cosméticos tradicionales: Refrescante en enjuagues bucales y pastas dentales; Aroma fresco y suave; Tónico ligero para piel. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Muy bien tolerada · En reflujo puede relajar el esfínter esofágico (menos que la piperita) · Moderar dosis muy altas en embarazo · No aplicar aceites de menta en la cara de bebés', 'hoja', false),
  ('Tilia Platyphyllos Flower Extract', 'Tilo', array['Calmante', 'Humectante']::text[], null, null, 'Tilia platyphyllos (Malvaceae). Parte usada: flor. Usos cosméticos tradicionales: Agua de tilo calmante para pieles sensibles y con rojeces; Descongestivo del contorno de ojos (compresas); Tónico suavizante (mucílagos). Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Muy bien tolerada · Dosis muy altas y frecuentes se han asociado (raramente) a molestias cardíacas — moderar · Sin contraindicaciones relevantes en dosis normales · Recolectar flores en zonas limpias', 'flor', false),
  ('Rosa Damascena Flower Extract', 'Rosa · Rosa de Damasco', array['Tonificante', 'Calmante']::text[], null, null, 'Rosa damascena (Rosaceae). Parte usada: flor. Usos cosméticos tradicionales: Agua de rosas: tónico equilibrante para todo tipo de piel; Calmante de rojeces y pieles sensibles o maduras; Antioxidante y antiedad (polifenoles). Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Muy bien tolerada · Diluir siempre el aceite esencial (es muy concentrado) · Posible alergia rara en personas sensibles · Usar pétalos libres de pesticidas (rosas de cultivo comestible)', 'flor', false),
  ('Achyrocline Satureioides Flower Extract', 'Marcela', array['Calmante', 'Antioxidante']::text[], null, null, 'Achyrocline satureioides (Asteraceae). Parte usada: flor. Usos cosméticos tradicionales: Extracto antioxidante y antiinflamatorio para la piel; Activo calmante para pieles reactivas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Posible alergia en sensibles a las Asteráceas · Moderar el uso medicinal en embarazo · Usar en dosis moderadas · Recolectar en zonas limpias · Tu ficha de vira-vira repite esta misma especie (Achyrocline satureioides); el vira-vira chileno suele ser otra planta (Pseudognaphalium viravira). Verifica', 'flor', false),
  ('Schinus Molle Fruit Extract', 'Molle · Pimiento', array['Antimicrobiano']::text[], null, null, 'Schinus molle (Anacardiaceae). Parte usada: fruto y hoja. Usos cosméticos tradicionales: Extracto astringente y antiséptico para piel grasa; Activo purificante. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'De la familia del litre y el mango: puede causar dermatitis en personas sensibles · Usar en dosis moderadas por vía interna · Evitar en embarazo · Prueba de parche antes del uso tópico extendido · Anacardiácea: puede dar alergia de contacto', 'fruto y hoja', false),
  ('Cestrum Parqui Leaf Extract', 'Palqui', array['Antimicrobiano']::text[], null, null, 'Cestrum parqui (Solanaceae). Parte usada: hoja. Usos cosméticos tradicionales: Uso cosmético muy limitado por su toxicidad. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'TÓXICO por vía interna (solanácea) — jamás ingerir · Solo uso externo tradicional, con prudencia · Los frutos son tóxicos, especialmente para niños y animales · Evitar en embarazo y en pieles muy reactivas · TÓXICO. Solanácea con saponinas y alcaloides; no usar en infusiones ni en preparados caseros. Se incluye solo para que se reconozca y se evite', 'hoja', false),
  ('Petroselinum Crispum Extract', 'Perejil', array['Antioxidante']::text[], null, null, 'Petroselinum crispum (Apiaceae). Parte usada: hoja y semilla. Usos cosméticos tradicionales: Aclarante suave de manchas (vitamina C); Tónico antioxidante y descongestivo para la piel; Extracto para el contorno de ojos. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'El apiol en dosis altas (y el aceite esencial) es abortivo y tóxico renal — no usar dosis medicinales altas en embarazo · Evitar dosis altas en enfermedad renal · Fotosensibilizante en dosis muy altas · El consumo culinario normal es seguro · Contiene furocumarinas: puede fotosensibilizar en uso concentrado', 'hoja y semilla', false),
  ('Apium Graveolens Extract', 'Apio', array['Calmante']::text[], null, null, 'Apium graveolens (Apiaceae). Parte usada: semilla. Usos cosméticos tradicionales: Extracto depurativo y antioxidante para la piel; Tónico para pieles congestionadas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Fotosensibilizante (furanocumarinas) — evitar el sol tras dosis altas · No usar dosis medicinales altas en embarazo ni en enfermedad renal · Posible alergia en sensibles a las Apiáceas · Puede potenciar diuréticos e hipotensores · Contiene furocumarinas: puede fotosensibilizar', 'semilla', false),
  ('Linum Usitatissimum Seed Extract', 'Lino · Linaza', array['Humectante', 'Formador de película', 'Gelificante']::text[], null, null, 'Linum usitatissimum (Linaceae). Parte usada: semilla. Usos cosméticos tradicionales: Gel de linaza para definir rizos y fijar el peinado (natural); Mucílago calmante y emoliente para la piel; Aceite nutritivo rico en omega-3 para pieles secas. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Tomar SIEMPRE con abundante agua — sin líquido puede obstruir el intestino · Contraindicado en obstrucción intestinal · Consumir molida para asimilar los nutrientes (entera pasa sin digerir) · El aceite se oxida rápido — conservar refrigerado · El gel se descompone en pocos días: refrigerar o conservar', 'semilla', false),
  ('Hibiscus Sabdariffa Flower Extract', 'Hibisco · Flor de Jamaica', array['Antioxidante', 'Colorante', 'Astringente']::text[], null, null, 'Hibiscus sabdariffa (Malvaceae). Parte usada: flor (cáliz). Usos cosméticos tradicionales: Exfoliante suave por sus AHA naturales; Tónico antiedad y unificante del tono; Acondicionador y aporte de color natural al cabello. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Baja la presión — precaución en hipotensión y con antihipertensivos · Evitar dosis altas en embarazo (emenagogo) · Su acidez puede molestar en gastritis · Puede reducir la absorción de algunos fármacos — separar', 'flor (cáliz)', false),
  ('Moringa Oleifera Leaf Extract', 'Moringa', array['Antioxidante']::text[], null, null, 'Moringa oleifera (Moringaceae). Parte usada: hoja. Usos cosméticos tradicionales: Aceite de moringa (ben): antiedad, purificante y estable; Extracto de hoja antioxidante para piel y cabello; Regenerador y protector frente a la contaminación. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'La RAÍZ y su corteza son tóxicas — usar solo la hoja y la semilla · Evitar los extractos concentrados y la raíz en el embarazo · Puede potenciar hipoglucemiantes e hipotensores · Usar en dosis moderadas · El aceite de la semilla está en Aceites vegetales', 'hoja', false),
  ('Spirulina Platensis Extract', 'Espirulina', array['Antioxidante', 'Colorante']::text[], null, null, 'Arthrospira platensis (Arthrospiraceae (cianobacteria)). Parte usada: microalga. Usos cosméticos tradicionales: Mascarillas detox y revitalizantes; Antioxidante y reafirmante para la piel; Aporte de clorofila y minerales; luminosidad. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Contraindicada en fenilcetonuria (contiene fenilalanina) · Precaución en enfermedades autoinmunes (estimula la inmunidad) · Comprar de fuente certificada: puede contaminarse con toxinas o metales · Consultar en embarazo y con anticoagulantes (vitamina K) · Puede teñir de verde-azul', 'microalga', false),
  ('Arctium Lappa Root Extract', 'Bardana · Lampazo', array['Calmante', 'Antimicrobiano']::text[], null, null, 'Arctium lappa (Asteraceae). Parte usada: raíz. Usos cosméticos tradicionales: Extracto de raíz para piel grasa y acneica (seborregulador y antibacteriano); Tónico capilar contra la caspa y la caída; Activo purificante y antioxidante. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Posible alergia en sensibles a las Asteráceas · Evitar en embarazo (emenagogo) · Puede potenciar hipoglucemiantes y diuréticos · Identificar bien la raíz al recolectar (no confundir con belladona)', 'raíz', false),
  ('Ugni Molinae Fruit Extract', 'Murta · Murtilla', array['Antioxidante']::text[], null, null, 'Ugni molinae (Myrtaceae). Parte usada: fruto. Usos cosméticos tradicionales: Extracto de fruto y hoja antioxidante y antiedad; Astringente suave para pieles mixtas; Aromatizante natural de cosmética. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Sin toxicidad relevante en uso alimentario y tópico habitual · En pieles muy sensibles, probar el extracto diluido', 'fruto', false),
  ('Berberis Microphylla Fruit Extract', 'Calafate', array['Antioxidante', 'Colorante']::text[], null, null, 'Berberis microphylla (Berberidaceae). Parte usada: fruto. Usos cosméticos tradicionales: Extracto de fruto antiedad y fotoprotector; Activo antioxidante para pieles maduras; Colorante natural morado. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'La berberina (corteza/raíz) puede interactuar con fármacos: evitar en embarazo y lactancia · Consumir el fruto bien maduro', 'fruto', false),
  ('Berberis Darwinii Extract', 'Michay', array['Antimicrobiano']::text[], null, null, 'Berberis darwinii (Berberidaceae). Parte usada: raíz y corteza. Usos cosméticos tradicionales: Extracto antibacteriano para piel acneica; Colorante amarillo natural; Tónico purificante. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Evitar en embarazo y lactancia (berberina) · Puede interactuar con fármacos y afectar el metabolismo hepático · No usar de forma prolongada · Contiene berberina, un alcaloide: evitar en embarazo', 'raíz y corteza', false),
  ('Gevuina Avellana Leaf Extract', 'Avellano Chileno · Gevuina', array['Emoliente']::text[], null, null, 'Gevuina avellana (Proteaceae). Parte usada: hoja y semilla. Usos cosméticos tradicionales: Aceite facial y corporal de rápida absorción; Fotoprotector y antioxidante natural; Reparador de la barrera cutánea. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Alergia a frutos secos en personas sensibles · Conservar el aceite protegido de luz y calor (se enrancia) · El aceite de la semilla está en Aceites vegetales. Evitar si hay alergia a frutos secos', 'hoja y semilla', false),
  ('Solanum Ligustrinum Leaf Extract', 'Natre', array['Calmante']::text[], null, null, 'Solanum ligustrinum (Solanaceae). Parte usada: hoja. Usos cosméticos tradicionales: Lavados para piel con granos o irritación (uso tradicional, diluido). Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Contiene alcaloides (Solanum): no exceder dosis ni uso prolongado · Evitar en embarazo, lactancia y niños · Preferir uso externo; internamente solo con orientación profesional · No confundir con otras solanáceas tóxicas · Solanácea: puede contener alcaloides. Uso tradicional externo; hacer prueba de parche', 'hoja', false),
  ('Achyrocline Satureioides Extract', 'Vira Vira', array['Calmante']::text[], null, null, 'Achyrocline satureioides (Asteraceae). Parte usada: flor y hoja. Usos cosméticos tradicionales: Vapores faciales descongestivos; Extracto antioxidante (flavonoides). Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Posible alergia en personas sensibles a las Asteráceas · Evitar dosis altas en embarazo · Tu ficha repite la especie de la marcela; verifica la especie real antes de usarla', 'flor y hoja', false),
  ('Centella Asiatica Extract', 'Centella Asiática · Gotu Kola', array['Cicatrizante', 'Calmante', 'Regenerador']::text[], null, null, 'Centella asiatica (Apiaceae). Parte usada: hoja. Usos cosméticos tradicionales: Sérums reparadores y antiedad (estimula colágeno); Calmante de pieles sensibles y con rojeces; Reafirmante y anticelulítico. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Evitar por vía interna en embarazo y lactancia · Puede causar dermatitis en personas muy sensibles · El uso interno prolongado puede afectar el hígado', 'hoja', false),
  ('Avena Sativa Kernel Extract', 'Avena', array['Calmante', 'Humectante']::text[], null, null, 'Avena sativa (Poaceae). Parte usada: grano. Usos cosméticos tradicionales: Avena coloidal en jabones y cremas calmantes; Mascarillas suavizantes e hidratantes; Limpiador suave para pieles sensibles. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Puede contener gluten por contaminación cruzada (celíacos, uso interno) · Sin riesgo relevante en uso tópico · En productos con agua se contamina con facilidad: necesita conservante', 'grano', false),
  ('Artemisia Absinthium Extract', 'Ajenjo', array['Antimicrobiano']::text[], null, null, 'Artemisia absinthium (Asteraceae). Parte usada: hoja. Usos cosméticos tradicionales: Loción astringente y antiparasitaria (uso externo, diluido); Enjuague capilar tradicional. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Contiene tuyona (neurotóxica): no exceder dosis ni uso prolongado · Contraindicado en embarazo y lactancia · Evitar en epilepsia y en úlcera gástrica · No apto para niños · Contiene tuyona (neurotóxica): no usar aceite esencial ni uso interno prolongado', 'hoja', false),
  ('Verbena Officinalis Extract', 'Verbena', array['Astringente', 'Calmante']::text[], null, null, 'Verbena officinalis (Verbenaceae). Parte usada: sumidad. Usos cosméticos tradicionales: Compresas antiinflamatorias para la piel; Tónico calmante. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Evitar en embarazo (estimula el útero) · Dosis altas pueden causar molestias digestivas · No confundir con la verbena de olor (cedrón, Aloysia)', 'sumidad', false),
  ('Symphytum Officinale Root Extract', 'Consuelda', array['Cicatrizante', 'Calmante']::text[], null, null, 'Symphytum officinale (Boraginaceae). Parte usada: raíz y hoja. Usos cosméticos tradicionales: Ungüentos y cremas reparadoras con alantoína; Bálsamos para piel agrietada; Activo regenerador antiedad (tópico). Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Solo uso externo: los alcaloides pirrolizidínicos son hepatotóxicos por vía oral · No aplicar sobre heridas abiertas profundas ni piel muy dañada · Evitar en embarazo y lactancia · No usar de forma prolongada · Contiene alcaloides pirrolizidínicos: solo sobre piel íntegra y sin uso prolongado', 'raíz y hoja', false),
  ('Ilex Paraguariensis Leaf Extract', 'Yerba Mate', array['Antioxidante', 'Estimulante']::text[], null, null, 'Ilex paraguariensis (Aquifoliaceae). Parte usada: hoja. Usos cosméticos tradicionales: Activo anticelulítico y reafirmante (cafeína); Contorno de ojos (descongestiona bolsas); Tónico capilar estimulante. Lo que se atribuye a la planta viene del uso tradicional; revisa su ficha para ver qué dicen los estudios.', 'floema', 'Ficha de planta de El Floema (lib/plantas-data.ts); borrador por verificar con la biblioteca científica', 'Extractos botánicos', 'Contiene cafeína: moderar en hipertensión, ansiedad e insomnio · Evitar el exceso durante el embarazo · El consumo muy caliente y prolongado se asocia a riesgo digestivo', 'hoja', false)
